-- Singular robotics market map: seed data, 103 companies.
-- Paste into the Supabase SQL editor and run AFTER schema.sql.
-- Safe to re-run: existing rows are updated by name.

on conflict (name) do update set
  url = excluded.url,
  category = excluded.category,
  vertical = excluded.vertical,
  country = excluded.country,
  description = excluded.description,
  met = excluded.met,
  met_by = excluded.met_by,
  met_date = excluded.met_date,
  total_raised = excluded.total_raised,
  last_round = excluded.last_round,
  last_round_size = excluded.last_round_size,
  last_round_date = excluded.last_round_date,
  lead_investors = excluded.lead_investors,
  notes = excluded.notes,
  source = excluded.source,
  pbid = excluded.pbid,
  pb_confidence = excluded.pb_confidence,
  pb_country = excluded.pb_country;
